    public List<ShippingMethod> testGetAll() throws Throwable {
    LOGGER.info( "ShippingMethodTest:testGetAll() - Retrieving Collection of ShippingMethods:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all ShippingMethod : " );
    List<ShippingMethod> collection  = null;

    try {
        // call the static get method on the ShippingMethodService
        collection = service.getAllShippingMethod();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            ShippingMethod currEntity  = null;
            Iterator<ShippingMethod> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getShippingMethodId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

